import sqlite3
import os
import argparse
import csv

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--db', required=True, help='Path to SQLite database file')
    parser.add_argument('--table', required=True, help='Name of the table to query')
    args = parser.parse_args()

    db_path = args.db
    table_name = args.table

    # Get the REPORT_TOKEN environment variable
    report_token = os.getenv('REPORT_TOKEN')
    if not report_token:
        sys.exit(3)

    # Validate table name - only allow alphanumeric, underscore, and dot
    if not table_name or not all(c.isalnum() or c in '_.' for c in table_name):
        sys.exit(3)

    # Validate that table name is a valid identifier (no SQL keywords)
    sql_keywords = {'select', 'from', 'where', 'and', 'or', 'drop', 'delete', 'update', 'insert', 'union', 'create', 'alter', 'truncate', 'grant', 'revoke', 'drop', 'table', 'view', 'procedure', 'function', 'trigger'}
    if any(kw in table_name.lower() for kw in sql_keywords):
        sys.exit(3)

    # Connect to the database
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
    except Exception as e:
        sys.exit(1)

    # Check if the access token is authorized for the table
    cursor.execute("SELECT 1 FROM access_tokens WHERE token = ? AND table_name = ?", (report_token, table_name))
    if cursor.fetchone() is None:
        sys.exit(3)

    # Read input lines from stdin
    lines = []
    try:
        for line in sys.stdin:
            line = line.strip()
            if line and '=' in line:
                parts = line.split('=', 1)
                column, value = parts[0].strip(), parts[1].strip()

                # Validate column name - only allow alphanumeric, underscore, dot
                if not column or not all(c.isalnum() or c in '_.' for c in column):
                    sys.exit(3)

                # Validate column name against SQL keywords
                if any(kw in column.lower() for kw in sql_keywords):
                    sys.exit(3)

                lines.append((column, value))
    except Exception as e:
        sys.exit(1)

    # Validate that the table has the required columns
    try:
        cursor.execute(f"PRAGMA table_info({table_name})")
        columns = {row[1] for row in cursor.fetchall()}
        for column, _ in lines:
            if column not in columns:
                sys.exit(3)
    except Exception as e:
        sys.exit(1)

    # Build the query with parameterized values
    query_parts = []
    if lines:
        conditions = []
        for column, value in lines:
            conditions.append(f"{column} = ?")
        query = f"SELECT id, name FROM {table_name} WHERE {' AND '.join(conditions)}"
        params = [value for column, value in lines]
    else:
        query = f"SELECT id, name FROM {table_name}"

    # Execute the query
    try:
        if lines:
            cursor.execute(query, params)
        else:
            cursor.execute(query)

        rows = cursor.fetchall()

        # Sort by id in ascending order
        rows.sort(key=lambda x: x[0])

        # Write header and rows
        print("id,name")
        for row in rows:
            print(f"{row[0]},{row[1]}")

    except Exception as e:
        sys.exit(1)

    sys.exit(0)

