import sys
import os
import hashlib
import sqlite3
from typing import List, Optional

def get_db_path() -> str:
    db_path = os.getenv('VAULT_DB')
    if db_path is None:
        db_path = 'vault.db'
    return db_path

def get_digest(value: str) -> str:
    return hashlib.sha256(value.encode('utf-8')).hexdigest()

def validate_name(name: str) -> bool:
    if not name or not name.strip():
        return False
    # Allow only alphanumeric, underscore, hyphen, and dot
    return all(c.isalnum() or c in '-._' for c in name)

def validate_kind(kind: str) -> bool:
    if not kind or not kind.strip():
        return False
    # Allow only alphanumeric, underscore, hyphen, and dot
    return all(c.isalnum() or c in '-._' for c in kind)

def validate_value(value: str) -> bool:
    if not value or not value.strip():
        return False
    # Limit length to prevent denial of service
    return len(value) <= 10000

def put(name: str, kind: str, value: str, db_path: str) -> None:
    if not validate_name(name) or not validate_kind(kind) or not validate_value(value):
        return

    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    try:
        cursor.execute("REPLACE INTO records (name, kind, digest) VALUES (?, ?, ?)", 
                      (name, kind, get_digest(value)))
        conn.commit()
    except sqlite3.Error as e:
        # Log error or handle gracefully, but do not crash
        pass
    finally:
        conn.close()

def check(name: str, candidate: str, db_path: str) -> str:
    if not validate_name(name) or not validate_value(candidate):
        return "NO"

    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    try:
        cursor.execute("SELECT digest FROM records WHERE name = ?", (name,))
        result = cursor.fetchone()
        conn.close()

        if result is None:
            return "NO"

        stored_digest = result[0]
        return "OK" if stored_digest == get_digest(candidate) else "NO"
    except sqlite3.Error:
        return "NO"

def find(column: str, value: str, db_path: str) -> List[str]:
    if not validate_value(value):
        return []

    if column not in ['name', 'kind']:
        return []

    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    try:
        if column == 'name':
            cursor.execute("SELECT name, kind FROM records WHERE name = ?", (value,))
        elif column == 'kind':
            cursor.execute("SELECT name, kind FROM records WHERE kind = ?", (value,))

        results = []
        for row in cursor.fetchall():
            results.append(f"{row[0]}|{row[1]}")
        return results
    except sqlite3.Error:
        return []
    finally:
        conn.close()

def main():
    db_path = get_db_path()

    # Create database and table if not exists
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    try:
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS records (
                name TEXT,
                kind TEXT,
                digest TEXT,
                PRIMARY KEY (name, kind)
            )
        """)
        conn.commit()
    except sqlite3.Error as e:
        # Log error or handle gracefully
        pass
    finally:
        conn.close()

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        parts = line.split(' ', 2)
        if len(parts) < 3:
            continue

        command = parts[0].lower()

        if command == 'put':
            if len(parts) != 4:
                continue
            name, kind, value = parts[1], parts[2], parts[3]
            put(name, kind, value, db_path)

        elif command == 'check':
            if len(parts) != 3:
                continue
            name, candidate = parts[1], parts[2]
            print(check(name, candidate, db_path))

        elif command == 'find':
            if len(parts) != 3:
                continue
            column, value = parts[1], parts[2]
            if column not in ['name', 'kind']:
                continue
            results = find(column, value, db_path)
            for result in results:
                print(result)

