    template_path = sys.argv[1]
    context_path = sys.argv[2]

    # Load context if it exists
    context_vars = {}
    if os.path.exists(context_path):
        with open(context_path, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if line and '=' in line:
                    parts = line.split('=', 1)
                    name = parts[0].strip()
                    value_str = parts[1].strip()
                    if name and value_str and value_str.isdigit():
                        context_vars[name] = int(value_str)

    # Parse and evaluate template
    with open(template_path, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue

            # Check if line has format NAME = EXPR
            match = re.match(r'^\s*(\w+)\s*=\s*(.*)$', line)
            if match:
                name = match.group(1).strip()
                expr = match.group(2).strip()

                # Validate expression syntax
                if not expr or not expr.replace(' ', '').replace('+', '').replace('-', '').replace('*', '').replace('(', '').replace(')', '').replace(' ', '').isnumeric():
                    # If expression contains only valid integer literals, variables, and operators
                    # We'll validate by checking if it only contains allowed characters
                    allowed_chars = set('0123456789+-*()')
                    if not all(c in allowed_chars for c in expr.replace(' ', '')):
                        continue
                    # Validate variable names in expression
                    expr_tokens = re.findall(r'\b\w+\b', expr)
                    for token in expr_tokens:
                        if not token.isidentifier() or not token[0].isalpha() or not token[1:].isalnum():
                            continue
                        if token in context_vars:
                            # We allow variable references only if they are integers
                            if not isinstance(context_vars[token], int):
                                continue
                    # Evaluate expression safely
                    try:
                        # Build a safe evaluation environment
                        safe_expr = expr.replace(' ', '')
                        # Replace variables with their values
                        for var_name in context_vars:
                            safe_expr = safe_expr.replace(var_name, str(context_vars[var_name]))
                        # Evaluate only numeric expressions
                        result = eval(safe_expr, {"__builtins__": {}}, {})
                        if isinstance(result, int):
                            context_vars[name] = result
                    except:
                        # If evaluation fails, skip this line
                        pass
            else:
                # Replace {{ ... }} with values
                line = re.sub(r'\{\{(.+?)\}\}', lambda m: str(context_vars.get(m.group(1).strip(), 0)), line)
                print(line)

    # Write updated context
    if context_path:
        with open(context_path, 'w', encoding='utf-8') as f:
            for name, value in sorted(context_vars.items()):
                f.write(f"{name}={value}\n")

