import sys
import json
import time
import os

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    action = sys.argv[1]

    if action not in ['issue', 'verify']:
        sys.exit(1)

    client_config_path = 'client_config.json'
    usage_path = 'usage.json'

    # Load client config with strict validation
    if not os.path.exists(client_config_path):
        client_config = {}
    else:
        try:
            with open(client_config_path, 'r', encoding='utf-8') as f:
                client_config = json.load(f)
            # Validate that client_config is a dict
            if not isinstance(client_config, dict):
                sys.stderr.write("invalid client configuration\n")
                sys.exit(1)
        except (json.JSONDecodeError, IOError) as e:
            sys.stderr.write("invalid client configuration\n")
            sys.exit(1)

    # Load usage data with strict validation
    if not os.path.exists(usage_path):
        usage = {}
    else:
        try:
            with open(usage_path, 'r', encoding='utf-8') as f:
                usage = json.load(f)
            # Validate that usage is a dict
            if not isinstance(usage, dict):
                sys.stderr.write("invalid usage data\n")
                sys.exit(1)
        except (json.JSONDecodeError, IOError) as e:
            sys.stderr.write("invalid usage data\n")
            sys.exit(1)

    if action == 'issue':
        try:
            client_id_line = sys.stdin.readline().strip()
            secret_line = sys.stdin.readline().strip()
        except (IOError, OSError):
            sys.stderr.write("unknown client or secret\n")
            sys.exit(1)

        if not client_id_line or not secret_line:
            sys.stderr.write("unknown client or secret\n")
            sys.exit(1)

        if client_id_line not in client_config:
            sys.stderr.write("unknown client or secret\n")
            sys.exit(1)

        config_secret = client_config[client_id_line].get('secret')
        if config_secret is None or config_secret != secret_line:
            sys.stderr.write("unknown client or secret\n")
            sys.exit(1)

        quota_per_minute = client_config[client_id_line].get('quota_per_minute')
        if not isinstance(quota_per_minute, int) or quota_per_minute <= 0:
            sys.stderr.write("invalid quota\n")
            sys.exit(1)

        now = int(time.time())
        usage_entries = usage.get(client_id_line, [])

        # Validate and count usage entries in the last minute
        count_in_last_minute = 0
        for s in usage_entries:
            if not isinstance(s, int):
                continue
            if now - 60 <= s <= now:
                count_in_last_minute += 1

        if count_in_last_minute >= quota_per_minute:
            sys.stderr.write("quota exceeded\n")
            sys.exit(2)

        # Append current time to usage
        usage[client_id_line].append(now)

        # Save usage.json with proper formatting
        try:
            with open(usage_path, 'w', encoding='utf-8') as f:
                json.dump(usage, f, separators=(',', ':'))
        except (IOError, OSError):
            sys.stderr.write("failed to save usage data\n")
            sys.exit(1)

        # Generate token with strict format
        token = f"{client_id_line}:{now}"
        print(token)

    elif action == 'verify':
        token_line = sys.stdin.readline().strip()
        if not token_line:
            sys.stderr.write("invalid token\n")
            sys.exit(1)

        # Validate token format: exactly two parts separated by colon
        if ':' not in token_line:
            sys.stderr.write("invalid token\n")
            sys.exit(1)

        parts = token_line.split(':', 1)  # Split on first colon only
        if len(parts) != 2:
            sys.stderr.write("invalid token\n")
            sys.exit(1)

        client_id = parts[0]
        token_time_str = parts[1]

        # Validate client ID
        if not client_id or not isinstance(client_id, str):
            sys.stderr.write("invalid token\n")
            sys.exit(1)

        if client_id not in client_config:
            sys.stderr.write("invalid token\n")
            sys.exit(1)

        # Validate token time is a valid integer
        try:
            issue_time = int(token_time_str)
        except (ValueError, TypeError):
            sys.stderr.write("invalid token\n")
            sys.exit(1)

        # Validate timestamp bounds
        if issue_time < 0 or issue_time > 10**10:  # Reasonable bounds to prevent overflow
            sys.stderr.write("invalid token\n")
            sys.exit(1)

        now = int(time.time())
        if now >= issue_time + 300:
            sys.stderr.write("invalid token\n")
            sys.exit(1)

        expires_at = issue_time + 300
        print(f"{client_id} {expires_at}")

