    # Ensure JSON data is a dictionary with integer values
    for key, value in json_data.items():
        if not isinstance(value, int):
            sys.exit(1)

    # Validate variable names: only allow alphanumeric and underscore, no built-ins
    # This prevents injection of dangerous names like 'os', 'eval', 'system'
    allowed_names = set()
    for key in json_data.keys():
        # Only allow identifiers that are safe (no built-ins)
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', key):
            sys.exit(1)
        allowed_names.add(key)

    # Create errors.log file if it doesn't exist
    errors_log = "errors.log"
    try:
        with open(errors_log, 'w') as f:
