import sys
import subprocess
import re

def parse_arithmetic_expression(expr):
    """
    Safely parse and evaluate a simple arithmetic expression with integers and +, -, *.
    Only supports basic operations and integer literals.
    """
    # Normalize whitespace
    expr = re.sub(r'\s+', ' ', expr)

    # Validate expression: only allow digits, +, -, *, and spaces
    if not re.match(r'^[\d+\-*/\s]+$', expr):
        return None

    # Split into tokens
    tokens = expr.split()
    if not tokens:
        return None

    # Validate tokens: each token must be a digit or one of the operators
    for token in tokens:
        if not (token.isdigit() or token in ['+', '-', '*']):
            return None

    # Evaluate safely using only basic arithmetic
    try:
        # Convert tokens to a list of numbers and operations
        values = []
        ops = []

        i = 0
        while i < len(tokens):
            if tokens[i].isdigit():
                values.append(int(tokens[i]))
            elif tokens[i] in ['+', '-', '*']:
                ops.append(tokens[i])
            i += 1

        # Evaluate with left-to-right precedence (only * has higher precedence)
        # First apply all * operations
        result = values[0] if values else 0
        i = 0
        while i < len(ops):
            if ops[i] == '*':
                result = result * values[i + 1]
                i += 1
            else:
                # For + and -, apply left-to-right
                if ops[i] == '+':
                    result += values[i + 1]
                elif ops[i] == '-':
                    result -= values[i + 1]
                i += 1

        return str(result)
    except Exception:
        return None

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    templates_file = sys.argv[1]

    try:
        with open(templates_file, 'r', encoding='utf-8') as file:
            lines = file.readlines()
    except FileNotFoundError:
        sys.exit(1)

    for line in lines:
        line = line.strip()
        if not line:
            continue

        # Replace {{...}} with evaluated expression using safe parsing
        # Use a simple regex to extract expressions between {{ and }}
        match = re.finditer(r'\{\{([^}]+)\}\}', line)
        for match_obj in match:
            expr = match_obj.group(1)
            evaluated = parse_arithmetic_expression(expr)
            if evaluated is None:
                # If expression is invalid, skip replacement
                continue
            # Replace the expression in the line
            line = line.replace(f"{{{{{{{expr}}}}}}}", evaluated)

        # Run the command without shell=True to avoid command injection
        # Use a list of arguments to avoid shell interpretation
        try:
            # Split the command into arguments to prevent shell injection
            # This ensures that only valid shell arguments are passed
            cmd_args = line.split()
            if not cmd_args:
                print("")
                continue

            # Run the command using subprocess with shell=False
            result = subprocess.run(cmd_args, capture_output=True, text=True, timeout=30)
            print(result.stdout)
        except subprocess.TimeoutExpired:
            print("")
        except Exception as e:
            print("")

