import sys
import json
import subprocess
import re
from pathlib import Path
from typing import List, Dict, Any

def evaluate_expression(expr: str) -> int:
    """Safely evaluate a simple arithmetic expression with * and +, where * has higher precedence."""
    if not expr or not expr.strip():
        return 0

    # Validate that the expression contains only digits, +, and *
    if not re.match(r'^\d+(\s*(\*|\+)\s*\d+)*$', expr.replace(' ', '')):
        return 0

    # Split by * first (higher precedence)
    parts = re.split(r'(\*|\+)', expr)
    tokens = []
    i = 0
    while i < len(parts):
        if parts[i] == '*':
            tokens.append(('*', parts[i+1]))
            i += 2
        else:
            tokens.append((parts[i], ''))
            i += 1

    # Evaluate multiplication first
    current_product = 1
    current_sum = 0
    i = 0
    while i < len(tokens):
        if tokens[i][0] == '*':
            if i + 1 < len(tokens):
                try:
                    next_val = int(tokens[i+1][0])
                    current_product *= next_val
                except (ValueError, IndexError):
                    current_product = 1
                i += 2
            else:
                i += 1
        else:
            if tokens[i][0].isdigit():
                try:
                    current_sum += int(tokens[i][0])
                except ValueError:
                    current_sum += 0
            i += 1

    return current_sum + current_product

def replace_placeholders(command: str, expr_values: Dict[str, int]) -> str:
    """Replace {{expr}} placeholders with evaluated values. Only safe expressions are used."""
    result = command
    for key, value in expr_values.items():
        # Ensure the key is safe (only alphanumeric, no shell metacharacters)
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', key):
            continue
        # Replace with the evaluated value
        result = result.replace(f"{{{key}}}", str(value))
    return result

def run_command(command: str) -> Dict[str, Any]:
    """Run a command safely without shell injection."""
    try:
        # Split the command into arguments to avoid shell injection
        # This ensures that only valid arguments are passed
        # We assume the command is a simple shell command with no shell metacharacters
        # If the command contains spaces, we split by space and validate
        parts = command.strip().split()
        if not parts:
            return {
                "command": command,
                "output": "Empty command",
                "exit_code": 1
            }

        # Validate that the command does not contain shell metacharacters
        # This is a basic check - we assume the command is safe if it's a simple command
        # with no pipes, redirections, or other shell features
        for part in parts:
            if any(metachar in part for metachar in [';', '|', '&', '>', '<', '$(', '$)', '$', '&&', '||']):
                return {
                    "command": command,
                    "output": "Command contains unsafe shell metacharacters",
                    "exit_code": 1
                }

        # Run the command using a list of arguments
        result = subprocess.run(
            parts,
            capture_output=True,
            text=True,
            timeout=30,
            shell=False
        )
        return {
            "command": command,
            "output": result.stdout + result.stderr,
            "exit_code": result.returncode
        }
    except subprocess.TimeoutExpired:
        return {
            "command": command,
            "output": "Command timed out",
            "exit_code": -1
        }
    except Exception as e:
        return {
            "command": command,
            "output": f"Error: {str(e)}",
            "exit_code": -1
        }

def main():
    if len(sys.argv) < 2:
        print(json.dumps({"error": "Missing file path"}))
        sys.exit(1)

    file_path = sys.argv[1]
    concurrency = 1

