    i = 2
    while i < len(sys.argv):
        if sys.argv[i] == '--concurrency':
            if i + 1 < len(sys.argv):
                try:
                    concurrency = int(sys.argv[i + 1])
                    if concurrency <= 0:
                        concurrency = 1
                except ValueError:
                    concurrency = 1
                i += 2
            else:
                i += 1
        else:
            i += 1

    # Validate file path
    try:
        path = Path(file_path)
        if not path.is_file():
