            sys.exit(1)

        with open(file_path, 'r', encoding='utf-8') as f:
            lines = f.readlines()
    except PermissionError:
        print(json.dumps({"error": f"Permission denied: {file_path}"}))
        sys.exit(1)
    except Exception as e:
        print(json.dumps({"error": f"Error reading file: {str(e)}"}))
        sys.exit(1)

    # Process each line
    commands = []
    for line in lines:
        line = line.strip()
        if not line:
            continue

        # Extract expressions like {{expr}} and evaluate them
        expr_matches = re.findall(r'\{\{(\w+)\}\}', line)
        expr_values = {}

        for expr in expr_matches:
            # Validate expression identifier
            if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', expr):
                expr_values[expr] = 0
                continue

            # Evaluate the expression safely
            try:
                value = evaluate_expression(expr)
                expr_values[expr] = value
            except Exception:
                expr_values[expr] = 0

        # Replace placeholders in the command
        processed_command = replace_placeholders(line, expr_values)
        commands.append(processed_command)

    # Run commands with concurrency
    results = []
    with subprocess.Popen(['python3'], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE) as proc:
        # Use a thread pool to run commands in parallel
        from concurrent.futures import ThreadPoolExecutor, as_completed
        with ThreadPoolExecutor(max_workers=concurrency) as executor:
            future_to_command = {executor.submit(run_command, cmd): cmd for cmd in commands}
            for future in as_completed(future_to_command):
                result = future.result()
