def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    manifest_path = sys.argv[1]
    max_parallel = int(sys.argv[2])

    if max_parallel <= 0:
        sys.exit(1)

    # Read and filter manifest lines
    with open(manifest_path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    # Filter out empty or whitespace-only lines
    commands = []
    for line in lines:
        stripped = line.strip()
        if stripped:
            # Validate command content: only allow safe, non-injectable tokens
            # Split by whitespace and check for dangerous patterns
            parts = stripped.split()
            # Check for common injection patterns (e.g., semicolon, pipe, dollar sign)
            if any(part in [';', '|', '&', '&&', '||', '$(', '$( ', '&&', '||', '>', '<', '>>', '<<'] for part in parts):
                # Skip if dangerous pattern detected
                continue
            # Only accept commands that are simple and do not contain shell metacharacters
            # For safety, we assume the command is a simple argument list
            commands.append(stripped)

    if not commands:
        sys.exit(0)

    # Execute commands in order with at most max_parallel running at once
    results = []
    running_count = 0
    command_index = 0

    def execute_next():
        nonlocal command_index, running_count
        while command_index < len(commands):
            # Get next command
            command = commands[command_index]
            command_index += 1

            # Validate command again to ensure no shell metacharacters
            if any(part in [';', '|', '&', '&&', '||', '>', '<', '>>', '<<', '$(', '$( ', '$', '(', ')'] for part in command.split()):
                # Skip if dangerous pattern detected
                continue

