                args = command.split()
                # Use subprocess with shell=False to avoid shell injection
                result = subprocess.run(args, capture_output=True, text=True, timeout=30)
                results.append((command_index - 1, result.returncode))
            except subprocess.TimeoutExpired:
                results.append((command_index - 1, "error"))
            except FileNotFoundError:
                results.append((command_index - 1, "error"))
            except PermissionError:
                results.append((command_index - 1, "error"))
            except Exception as e:
                results.append((command_index - 1, "error"))

            running_count -= 1
            # If we have fewer than max_parallel running, start the next one
            if running_count < max_parallel and command_index < len(commands):
                # Start next command
                execute_next()
            break

    # Execute commands sequentially with at most max_parallel running at once
    # We simulate parallel execution by running commands in batches
    # But without shell injection or unsafe threading
    for i in range(0, len(commands), max_parallel):
