        for cmd in batch:
            # Validate command again
            if any(part in [';', '|', '&', '&&', '||', '>', '<', '>>', '<<', '$(', '$( ', '$', '(', ')'] for part in cmd.split()):
                continue

            try:
                args = cmd.split()
                result = subprocess.run(args, capture_output=True, text=True, timeout=30)
                results.append((commands.index(cmd), result.returncode))
            except subprocess.TimeoutExpired:
                results.append((commands.index(cmd), "error"))
            except FileNotFoundError:
                results.append((commands.index(cmd), "error"))
            except PermissionError:
                results.append((commands.index(cmd), "error"))
            except Exception as e:
                results.append((commands.index(cmd), "error"))

    # Print DONE messages as commands finish
    for cmd_index, exit_code in results:
        if isinstance(exit_code, int) and exit_code != 0:
            print(f"DONE {cmd_index} exit={exit_code}")
        elif exit_code == "error":
            print(f"DONE {cmd_index} exit=error")

    # Check final exit status
    all_success = True
    for cmd_index, exit_code in results:
        if isinstance(exit_code, int) and exit_code != 0:
            all_success = False
        elif exit_code == "error":
            all_success = False

    sys.exit(0 if all_success else 1)

