            if '..' in db_path or os.path.isabs(db_path) and not db_path.startswith('/'):
                sys.exit(1)

            # Validate query element
            query_elem = root.find('.//query')
            if query_elem is None:
                sys.exit(1)
            query_text = query_elem.text.strip()
            if not query_text:
                sys.exit(1)

            # Validate query structure: must contain exactly one ? and only safe operations
            if '?' not in query_text:
