import os
import sys
import stat
from pathlib import Path

def get_file_size(path):
    try:
        # Normalize path to ensure it's absolute and safe
        normalized_path = Path(path).resolve()
        # Check if the path is a file and not a directory
        if not normalized_path.is_file():
            return None
        return normalized_path.stat().st_size
    except (OSError, IOError):
        return None

def load_cache():
    cache_file = '.stats_cache'
    if os.path.exists(cache_file):
        cache = {}
        try:
            with open(cache_file, 'r') as f:
                for line in f:
                    line = line.strip()
                    if line:
                        parts = line.split('\t')
                        if len(parts) == 2:
                            path, size = parts[0], parts[1]
                            cache[path] = int(size)
        except (OSError, IOError):
            pass  # Ignore errors when reading cache
        return cache
    return {}

def save_cache(cache):
    cache_file = '.stats_cache'
    try:
        # Ensure the cache file is created with proper permissions
        os.makedirs(os.path.dirname(cache_file), exist_ok=True)
        with open(cache_file, 'w') as f:
            for path in sorted(cache.keys()):
                f.write(f"{path}\t{cache[path]}\n")
        # Set file permissions to be readable and writable only by owner
        os.chmod(cache_file, stat.S_IRUSR | stat.S_IWUSR)
    except (OSError, IOError):
        # Log or handle error, but continue execution
        pass

def main():
    cache = load_cache()
    paths = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            # Validate path: ensure it contains only valid characters and is not empty
            if not line or not all(c.isalnum() or c in '.-_/' for c in line):
                continue
            paths.append(line)

    # Process paths in groups of up to 4
    groups = [paths[i:i+4] for i in range(0, len(paths), 4)]

    for group in groups:
        for path in group:
            # Normalize path to avoid traversal
            normalized_path = Path(path).resolve()
            if normalized_path.is_file():
                # Check if the path is within a safe directory (relative to current working directory)
                current_dir = Path.cwd()
                if not (current_dir / normalized_path).is_relative_to(current_dir):
                    # Path traversal detected
                    print(f"{path}\tERROR")
                    continue
                if path in cache:
                    print(f"{path}\t{cache[path]}")
                else:
                    size = get_file_size(path)
                    if size is not None:
                        cache[path] = size
                        print(f"{path}\t{size}")
                    else:
                        print(f"{path}\tERROR")
            else:
                if path in cache:
                    print(f"{path}\t{cache[path]}")
                else:
                    print(f"{path}\tERROR")

    # Save the updated cache with proper permissions
    save_cache(cache)

if __name__ == "__main__":
    main()

import sys
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from urllib.parse import urlparse
import re

def is_valid_url(url):
    """Validate if the URL has a proper format using a regex pattern."""
    # Basic URL pattern: http(s):// or ftp:// with domain or IP
    pattern = re.compile(
        r'^https?://(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z0-9][a-zA-Z0-9-]{0,61}[a-zA-Z0-9](?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$'
    )
    return bool(pattern.match(url))

def fetch_url(url):
    """Send an HTTP GET request with timeout and return status code or ERROR."""
    try:
        if not is_valid_url(url):
            return url, "ERROR"
        response = requests.get(url, timeout=10)
        return url, response.status_code
    except requests.exceptions.RequestException:
        return url, "ERROR"

def main():
    # Read file path from stdin
    file_path = sys.stdin.readline().strip()
    if not file_path:
        return

    # Validate file path to prevent path traversal
    # Allow only absolute paths that start with a known directory or use a whitelist
    # For security, we restrict to paths that are absolute and do not contain directory traversal
    if not file_path.startswith('/'):
        print("ERROR: Invalid file path - must be absolute", file=sys.stderr)
        return

    # Prevent path traversal using basic checks
    if '..' in file_path or '~' in file_path or '//' in file_path:
        print("ERROR: Invalid file path - contains path traversal attempt", file=sys.stderr)
        return

    # Open the file and read URLs
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            urls = [line.strip() for line in file if line.strip()]
    except (OSError, IOError) as e:
        print(f"ERROR: Failed to open file: {e}", file=sys.stderr)
        return

    results = []
    with ThreadPoolExecutor(max_workers=3) as executor:
        future_to_url = {executor.submit(fetch_url, url): url for url in urls}
        for future in as_completed(future_to_url):
            url = future_to_url[future]
            try:
                result = future.result()
                results.append(result)
            except Exception as exc:
                results.append((url, "ERROR"))

    # Output results
    for url, status in results:
        print(f"{url} {status}")

if __name__ == "__main__":
    main()

import sys
import time
import requests
from urllib.parse import urlparse
import os

def main():
    if len(sys.argv) != 2:
        print("Usage: python fetch.py urls.txt")
        return

    urls_file = sys.argv[1]
    tokens_file = "tokens.txt"

    # Validate that tokens.txt exists and is readable
    if not os.path.exists(tokens_file):
        print(f"Error: {tokens_file} not found")
        return

    urls = []
    with open(urls_file, 'r') as f:
        for line in f:
            line = line.strip()
            if line:
                urls.append(line)

    # Read tokens with validation
    tokens = {}
    with open(tokens_file, 'r') as f:
        for line in f:
            line = line.strip()
            if line:
                parts = line.split('\t', 1)  # Split only on first tab
                if len(parts) == 2:
                    hostname, token = parts[0].strip(), parts[1].strip()
                    if hostname and token:
                        tokens[hostname] = token

    # Process each URL with input validation and secure handling
    for i, url in enumerate(urls):
        try:
            # Validate URL format
            if not url or not isinstance(url, str):
                print(f"DENIED {url}")
                continue

            parsed = urlparse(url)
            if not parsed.scheme or not parsed.netloc:
                print(f"DENIED {url}")
                continue

            # Extract hostname safely
            hostname = parsed.netloc

            # Validate hostname format (only allow valid domain-like structure)
            if not is_valid_hostname(hostname):
                print(f"DENIED {url}")
                continue

            # Check if token exists for this hostname
            if hostname not in tokens:
                print(f"DENIED {url}")
                continue

            token = tokens[hostname]

            # Construct headers securely
            headers = {"Authorization": f"Bearer {token}"}

            # Send HTTP GET request with timeout
            start_time = time.time()
            response = requests.get(url, headers=headers, timeout=5)

            # Only print success if within timeout
            if time.time() - start_time < 5:
                print(f"{response.status_code} {url}")
            else:
                print(f"ERROR {url}")

        except requests.exceptions.Timeout:
            print(f"ERROR {url}")
        except requests.exceptions.RequestException as e:
            print(f"ERROR {url}")

        # Apply delay between requests (except first)
        if i < len(urls) - 1:
            time.sleep(0.7)

def is_valid_hostname(hostname):
    """Validate hostname format: only allow standard domain format"""
    # Basic validation: must have at least one dot, no control characters
    if not hostname or not isinstance(hostname, str):
        return False

    # Check for valid domain-like structure
    # Must contain at least one dot, and no invalid characters
    if hostname.startswith('[') or hostname.endswith(']'):
        return False

    # Allow common domain patterns (e.g., example.com, sub.example.com)
    # Reject IP addresses (e.g., 192.168.1.1) or malformed formats
    if hostname.count('.') < 1:
        return False

    # Check for invalid characters (only alphanumeric, hyphens, dots)
    for char in hostname:
        if not (char.isalnum() or char in '._-'):
            return False

    # Ensure no leading/trailing dots or hyphens
    if hostname.startswith('.') or hostname.endswith('.'):
        return False

    return True

