import sys
import re
import xml.etree.ElementTree as ET
import operator
from typing import Dict, List, Tuple

# Define supported operations
OPERATIONS = {
    '+': operator.add,
    '-': operator.sub,
    '*': operator.mul,
    '/': operator.truediv
}

# Tokenizer for arithmetic expressions
def tokenize(expression: str) -> List[str]:
    # Remove whitespace and split by operators and numbers
    tokens = []
    i = 0
    while i < len(expression):
        char = expression[i]
        if char in '+-*/':
            tokens.append(char)
            i += 1
        elif char.isdigit() or char == '.' or char == '-':
            # Extract full number (including negative numbers)
            num_start = i
            while i < len(expression) and (expression[i].isdigit() or expression[i] == '.'):
                i += 1
            tokens.append(expression[num_start:i])
        elif char.isalpha():
            # Extract variable name (letters only)
            var_start = i
            while i < len(expression) and expression[i].isalpha():
                i += 1
            tokens.append(expression[var_start:i])
        else:
            i += 1
    return tokens

# Validate tokens for arithmetic expression
def is_valid_token(token: str) -> bool:
    # Must be a number or a letter-only variable name
    if token.replace('.', '').isdigit():
        return True
    if token[0] == '-' and len(token) > 1 and token[1:].replace('.', '').isdigit():
        return True
    if token.isalpha():
        return True
    return False

# Parse expression using a safe, recursive descent parser
def parse_expression(tokens: List[str], variables: Dict[str, float]) -> float:
    if not tokens:
        raise ValueError("Empty expression")

    # Build expression from tokens
    def parse_term():
        # Parse a term (number or variable)
        token = tokens.pop(0)
        if not is_valid_token(token):
            raise ValueError(f"Invalid token: {token}")

        if token in variables:
            return variables[token]
        if token.replace('.', '').isdigit():
            try:
                return float(token)
            except ValueError:
                raise ValueError(f"Invalid number: {token}")
        else:
            raise ValueError(f"Invalid variable or number: {token}")

    # Parse expression with binary operations
    def parse_expression():
        left = parse_term()
        while tokens and tokens[0] in OPERATIONS:
            op = tokens.pop(0)
            right = parse_term()
            if op not in OPERATIONS:
                raise ValueError(f"Invalid operator: {op}")
            left = OPERATIONS[op](left, right)
        return left

    try:
        result = parse_expression()
        return result
    except Exception as e:
        raise ValueError(f"Invalid expression: {str(e)}")

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    xml_path = sys.argv[1]

    # Parse XML file
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except ET.ParseError as e:
        sys.exit(1)
    except FileNotFoundError:
        sys.exit(1)

    # Read variable values from stdin
    variables = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        match = re.match(r'^([a-zA-Z]+)=(-?\d+\.?\d*|\d*\.?\d+)$', line)
        if match:
            var_name = match.group(1)
            var_value = float(match.group(2))
            variables[var_name] = var_value
        else:
            # Log warning or skip invalid line
            continue

    # Process each field in order
    for field in root.findall('field'):
        name = field.get('name')
        expr = field.text.strip() if field.text else ""
        if not expr:
            continue

        # Validate expression tokens
        tokens = tokenize(expr)
        try:
            result = parse_expression(tokens, variables)
            print(f"{name}={result}")
        except ValueError as e:
            sys.exit(1)

if __name__ == "__main__":
    main()

