def validate_column_name(name):
    """Validate column name to prevent SQL injection."""
    if not name or not isinstance(name, str):
        return False
    # Allow only alphanumeric, underscore, and dot (for safe column names)
    if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', name):
        return False
    return True

def validate_table_name(name):
    """Validate table name to prevent SQL injection."""
    if not name or not isinstance(name, str):
        return False
    # Allow only alphanumeric, underscore, and dot (for safe table names)
    if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', name):
        return False
    return True

def validate_output_path(path, base_dir):
    """Validate output path to prevent directory traversal."""
    if not path or not isinstance(path, str):
        return False
    # Normalize path and check for traversal
    normalized = os.path.normpath(path)
    # Check if path is absolute and starts with base_dir or is within base_dir
    if os.path.isabs(normalized):
        # If absolute, must be within base_dir
        if not normalized.startswith(base_dir):
            return False
        # Check for directory traversal
        if '..' in normalized:
            return False
    else:
        # Relative path - must be within base_dir
        full_path = os.path.join(base_dir, normalized)
        if '..' in normalized or not os.path.commonpath([full_path]) == base_dir:
            return False
    return True

def execute_query_safe(spec, db_path, base_dir):
    table = spec['table']
    columns = spec['columns']
    filters = spec['filters']
    output_path = spec['output']

    # Validate inputs
    if not isinstance(spec, dict):
        return {'output': output_path, 'rows': 0}
    if not isinstance(table, str) or not validate_table_name(table):
        return {'output': output_path, 'rows': 0}
    if not isinstance(columns, list) or not all(validate_column_name(col) for col in columns):
        return {'output': output_path, 'rows': 0}
    if not isinstance(output_path, str):
        return {'output': output_path, 'rows': 0}

    # Validate output path
    if not validate_output_path(output_path, base_dir):
        return {'output': output_path, 'rows': 0}

    # Connect to database
    try:
        conn = sqlite3.connect(db_path)
        conn.row_factory = sqlite3.Row  # Enable column access by name
        cursor = conn.cursor()
    except Exception as e:
        return {'output': output_path, 'rows': 0}

    # Build the SELECT query with safe column names
    select_clause = ", ".join([f"{col}" for col in columns])
    query = f"SELECT {select_clause} FROM {table}"

    # Add WHERE clause if filters exist
    where_clauses = []
    params = []
    for col, value in filters.items():
        if not isinstance(col, str) or not validate_column_name(col):
            conn.close()
            return {'output': output_path, 'rows': 0}
        if not isinstance(value, str):
            conn.close()
            return {'output': output_path, 'rows': 0}
        where_clauses.append(f"{col} = ?")
        params.append(value)
    if where_clauses:
        query += " WHERE " + " AND ".join(where_clauses)

    # Execute query
    try:
        cursor.execute(query, params)
        rows = cursor.fetchall()
    except Exception as e:
        conn.close()
        return {'output': output_path, 'rows': 0}

    # Close connection
    conn.close()

    # Write rows to output file
    output_data = []
    for row in rows:
        row_dict = {}
        for col in columns:
            row_dict[col] = row[col] if row[col] is not None else None
        output_data.append(row_dict)

    # Write to file in safe directory
    try:
        output_dir = os.path.dirname(output_path)
        if output_dir and not os.path.exists(output_dir):
            os.makedirs(output_dir, exist_ok=True)
        with open(output_path, 'w', encoding='utf-8') as f:
            json.dump(output_data, f, indent=2, ensure_ascii=False)
    except Exception as e:
        return {'output': output_path, 'rows': 0}

    return {
        'output': output_path,
        'rows': len(output_data)
    }

def process_spec(spec, db_path, result_queue, base_dir):
    try:
        result = execute_query_safe(spec, db_path, base_dir)
        result_queue.put(result)
    except Exception as e:
        result_queue.put({
            'output': spec['output'],
            'rows': 0
        })

