def parse_expression(expr, row, table_columns):
    # Validate expression syntax using a strict regex
    # Only allow digits, decimals, +, -, *, /, (, ), spaces, and column names
    # Column names must be valid identifiers (alphanumeric, underscore)
    pattern = r'^\s*([0-9]+(\.[0-9]+)?|[a-zA-Z_][a-zA-Z0-9_]*)\s*(\+\s*|-\s*|\*\s*|\/\s*)\s*([0-9]+(\.[0-9]+)?|[a-zA-Z_][a-zA-Z0-9_]*)\s*(\+\s*|-\s*|\*\s*|\/\s*)\s*([0-9]+(\.[0-9]+)?|[a-zA-Z_][a-zA-Z0-9_]*)\s*(\(\s*\)|\s*)\s*$'
    # This is a simplified parser - we'll use a recursive descent approach for safety
    # Instead, we'll use a safe evaluation with a whitelist of operations and variables

    # First, validate that the expression only contains allowed tokens
    # Allowed tokens: numbers, column names, +, -, *, /, (, )
    # Column names must be in the table columns list
    tokens = []
    token = ""
    i = 0
    while i < len(expr):
        c = expr[i]
        if c in "()+-*/":
            if token:
                tokens.append(token)
