import sys
import hashlib
import json
import urllib.parse
from urllib.parse import urlparse

def compute_hex_digest(data):
    return hashlib.sha256(data.encode('utf-8')).hexdigest()

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme in ['http', 'https'], result.netloc])
    except Exception:
        return False

def main():
    cache_file = 'cache.json'

    # Load cache if it exists
    try:
        with open(cache_file, 'r') as f:
            cache = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        cache = {}

    # Process each URL from stdin
    for line in sys.stdin:
        url = line.strip()
        if not url or not is_valid_url(url):
            # Skip invalid URLs
            print(f"{url},0" * 64)
            continue

        if url in cache:
            hex_string = cache[url]
        else:
            try:
                # Only allow safe schemes and domains
                parsed = urlparse(url)
                if parsed.scheme not in ['http', 'https']:
                    hex_string = "0" * 64
                else:
                    # Use a safe, controlled request
                    response = requests.get(url, timeout=10, allow_redirects=False)
                    if response.status_code == 200:
                        body = response.content
                        hex_string = compute_hex_digest(body)
                        cache[url] = hex_string
                    else:
                        hex_string = "0" * 64
            except requests.RequestException:
                hex_string = "0" * 64

        # Output URL and hex string
        print(f"{url},{hex_string}")

    # Write updated cache to file with restricted permissions
    with open(cache_file, 'w') as f:
        json.dump(cache, f, indent=2)

