    for url, expression in config.items():
        try:
            # Validate expression syntax using ast
            tree = ast.parse(expression, mode='eval')

            # Validate that the expression only contains safe operations
            # Only allow field access (e.g., item['count']), arithmetic, and built-in functions
            safe_functions = {'abs', 'int', 'float', 'len', 'sum', 'max', 'min', 'bool'}

            def validate_node(node):
                if isinstance(node, ast.Name):
                    return node.id in ['item']
                elif isinstance(node, ast.Subscript):
                    return isinstance(node.value, ast.Name) and node.value.id == 'item'
                elif isinstance(node, ast.BinOp):
                    left = validate_node(node.left)
                    right = validate_node(node.right)
                    return left and right
                elif isinstance(node, ast.UnaryOp):
                    return validate_node(node.operand)
                elif isinstance(node, ast.Call):
                    func = validate_node(node.func)
                    if func and isinstance(func, str):
                        return func in safe_functions
                    return False
                elif isinstance(node, ast.Constant):
                    return True
                return False

            if not validate_node(tree.body):
                print(f"Error: Unsafe expression in {url}")
                output[url] = []
                continue

            response = requests.get(url)
            response.raise_for_status()
            data = response.json()

            values = []
            for item in data:
                try:
                    # Safely evaluate expression using ast.literal_eval-like logic
                    # We use a custom evaluation that only allows safe operations
                    result = eval_expression(expression, item)
                    if isinstance(result, int):
                        values.append(result)
                    else:
                        # Skip if result is not an integer
                        pass
                except Exception as e:
                    print(f"Error processing item in {url}: {e}")
                    continue

            output[url] = values
        except requests.RequestException as e:
            print(f"Error fetching {url}: {e}")
            output[url] = []
        except Exception as e:
            print(f"Error processing {url}: {e}")
            output[url] = []

    with open(output_file_path, 'w') as output_file:
        json.dump(output, output_file, indent=2)

def eval_expression(expression: str, item: Dict[str, Any]) -> Any:
    """
    Safely evaluate an expression using only safe operations.
    Only allows field access on 'item' and basic arithmetic.
    """
    # Replace any references to 'item' with a safe access
    # We use a safe evaluator that only allows field access and arithmetic
    try:
        # Use a restricted namespace with only 'item' and built-in functions
        safe_globals = {
            'item': item,
            'abs': abs,
            'int': int,
            'float': float,
            'len': len,
            'sum': sum,
            'max': max,
            'min': min,
            'bool': bool
        }

        # Evaluate the expression in a safe context
        # We use eval with restricted globals
        result = eval(expression, safe_globals)

        # Ensure result is an integer
        if isinstance(result, (int, float)) and result == int(result):
            return int(result)
        else:
            return None

    except Exception as e:
        # If evaluation fails, return None
        return None

