                print(f"Command failed for {current_owner}: {result.stderr}", file=sys.stderr)
        except subprocess.TimeoutExpired:
            print(f"Command timeout for {current_owner}", file=sys.stderr)
            continue
        except Exception as e:
            print(f"Command execution error for {current_owner}: {str(e)}", file=sys.stderr)
            continue

        # Append current time to the array
        state[current_owner].append(now)

    # Remove timestamps less than now - 60 from all owners' arrays
    current_time = time.time()
    cutoff = current_time - 60

    for owner in state:
        # Filter timestamps to only those >= cutoff
        state[owner] = [ts for ts in state[owner] if ts >= cutoff]

    # Write updated state to state.json with validation
    try:
        with open(state_file, 'w', encoding='utf-8') as f:
            json.dump(state, f, indent=2, separators=(',', ': '))
    except IOError as e:
        print(f"Error writing state file: {str(e)}", file=sys.stderr)
        sys.exit(1)

