    # We need to ensure that // is only used between numbers and not in invalid positions
    # Split by whitespace and validate each token
    tokens = re.split(r'(\s+)', expr)
    tokens = [t.strip() for t in tokens if t.strip()]

    # Validate tokens: each token must be either a number or one of the operators
    valid_tokens = []
    for token in tokens:
        if token in ['+', '-', '*', '//']:
            valid_tokens.append(token)
        elif token.isdigit():
            valid_tokens.append(token)
        else:
            return 0

    # Reconstruct expression with only valid tokens
    expr_clean = re.sub(r'\s+', ' ', expr).strip()

    # Check for valid expression structure
    # Must have at least one number
    if not any(t.isdigit() for t in tokens):
        return 0

    # Validate that operators are properly placed
    # We'll use a simple stack-based evaluation with only allowed operations
    try:
        # Replace // with integer division
        expr_clean = expr_clean.replace('//', ' // ')

        # Evaluate using a safe parser
        # We'll use a simple recursive descent parser with only allowed operations
        # This avoids eval() entirely

        # Parse and evaluate using a safe method
        # We'll use a stack-based evaluation with only allowed operations
        def tokenize(expr):
            tokens = []
            i = 0
            while i < len(expr):
                if expr[i].isspace():
                    i += 1
                elif expr[i].isdigit():
                    num = ''
                    while i < len(expr) and expr[i].isdigit():
                        num += expr[i]
                        i += 1
                    tokens.append(num)
                elif expr[i] in '+-*/':
                    tokens.append(expr[i])
                    i += 1
                elif expr[i] == '(':
                    tokens.append('(')
                    i += 1
                elif expr[i] == ')':
                    tokens.append(')')
                    i += 1
                else:
                    i += 1
            return tokens

        def evaluate(tokens):
            if not tokens:
                return 0

            # Convert to list of tokens
            stack = []
            i = 0

            while i < len(tokens):
                token = tokens[i]
                if token == '(':
                    # Find matching closing parenthesis
                    depth = 1
                    j = i + 1
                    while j < len(tokens) and depth > 0:
                        if tokens[j] == '(':
                            depth += 1
                        elif tokens[j] == ')':
                            depth -= 1
                        j += 1
                    # Extract subexpression
                    sub_tokens = tokens[i+1:j-1]
                    sub_result = evaluate(sub_tokens)
                    stack.append(str(sub_result))
                    i = j - 1
                elif token == '+' or token == '-' or token == '*' or token == '//':
                    # Handle binary operators
                    if len(stack) >= 2:
                        b = int(stack.pop())
                        a = int(stack.pop())
                        if token == '+':
                            stack.append(str(a + b))
                        elif token == '-':
                            stack.append(str(a - b))
                        elif token == '*':
                            stack.append(str(a * b))
                        elif token == '//':
                            if b == 0:
                                return 0
                            stack.append(str(a // b))
                    else:
                        return 0
                else:
                    # Token is a number
                    stack.append(token)
                i += 1

            # Final result
            if len(stack) == 1:
                return int(stack[0])
            else:
                return 0

        tokens = tokenize(expr_clean)
        return evaluate(tokens)

    except Exception:
        return 0

def expand_xml(input_path, output_path):
    # Create cache file path
    cache_path = input_path + ".expandcache"

    # Load cache if it exists
    cache = {}
    if os.path.exists(cache_path):
        try:
            with open(cache_path, 'r', encoding='utf-8') as f:
                cache_data = f.read()
                # Parse cache data safely - only store as dictionary of strings and integers
                # We will validate the structure
                try:
                    # Try to parse as JSON-like structure
                    import json
                    cache = json.loads(cache_data)
                    # Validate that cache is a dict with string keys and int values
                    for k, v in cache.items():
                        if not isinstance(k, str) or not isinstance(v, int):
                            cache = {}
                            break
                except (json.JSONDecodeError, ValueError):
                    cache = {}
        except Exception:
            cache = {}

    # Read input XML
    try:
        with open(input_path, 'r', encoding='utf-8') as f:
            xml_content = f.read()
    except Exception as e:
        print(f"Error reading input file: {e}")
        sys.exit(1)

    # Find all placeholders of the form {{ expr }}
    placeholders = re.findall(r'\{\{([^}]+)\}\}', xml_content)

    # Replace placeholders with evaluated expressions
    result_content = xml_content
    replacements = 0
    cache_hits = 0

    for placeholder in placeholders:
        expr = placeholder.strip()
        # Validate expression format
        if not expr or not re.match(r'^[\d\s+\-*/\(\)]+$', expr):
            # Invalid expression - skip
            continue

        # Check if we have a cached result
        if expr in cache:
            cache_hits += 1
            result_content = result_content.replace(f"{{{{ {expr} }}}}", str(cache[expr]))
        else:
            # Evaluate expression safely
            value = safe_evaluate_expression(expr)
            cache[expr] = value
            replacements += 1
            result_content = result_content.replace(f"{{{{ {expr} }}}}", str(value))

    # Write output XML
    try:
        with open(output_path, 'w', encoding='utf-8') as f:
            f.write(result_content)
    except Exception as e:
        print(f"Error writing output file: {e}")
        sys.exit(1)

    # Save cache in safe format (JSON)
    try:
        import json
        with open(cache_path, 'w', encoding='utf-8') as f:
            json.dump(cache, f, indent=2)
    except Exception as e:
        print(f"Error saving cache: {e}")
        sys.exit(1)

    # Print the required output
    print(f"Replaced {replacements} placeholders ({cache_hits} from cache).")

