import sys
import json
import time
import os
from urllib.parse import urlparse
from urllib.request import urlopen
from urllib.error import URLError, HTTPError

def is_valid_url(url: str) -> bool:
    """Validate URL format to prevent open redirects, SSRF, and malformed inputs."""
    try:
        result = urlparse(url)
        return all([result.scheme in ['http', 'https'], result.netloc])
    except Exception:
        return False

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    urls_file = sys.argv[1]
    cache_file = sys.argv[2]

    log_file = "cacher.log"

    # Initialize log file
    if not os.path.exists(log_file):
        open(log_file, "w", encoding="utf-8").close()

    # Initialize cache
    cache = {}

    # Read cache file if exists
    if os.path.exists(cache_file):
        try:
            with open(cache_file, "r", encoding="utf-8") as f:
                cache_data = json.load(f)
                if isinstance(cache_data, dict):
                    # Validate cache structure
                    for url, entry in cache_data.items():
                        if not isinstance(entry, dict):
                            continue
                        if 'retrieved_at' not in entry or 'body' not in entry:
                            continue
                        if not isinstance(entry['retrieved_at'], (int, float)):
                            continue
                        if not isinstance(entry['body'], str):
                            continue
                    cache = cache_data
                else:
                    cache = {}
        except (json.JSONDecodeError, IOError):
            cache = {}

    # Get current time in seconds
    current_epoch_seconds = time.time()

    # Open log file for appending
    with open(log_file, "a", encoding="utf-8") as log:
        with open(urls_file, "r", encoding="utf-8") as urls:
            failed_urls = 0
            last_retrieval_time = 0

            for line in urls:
                line = line.rstrip()
                if not line:
                    continue

                url = line.strip()

                # Validate URL
                if not is_valid_url(url):
                    log_entry = {
                        "url": url,
                        "event": "failed",
                        "seconds": time.time() - current_epoch_seconds
                    }
                    log.write(json.dumps(log_entry) + "\n")
                    print()
                    failed_urls += 1
                    continue

                # Check cache for hit
                cache_hit = False
                cache_entry = cache.get(url)

                if cache_entry and cache_entry["retrieved_at"] >= current_epoch_seconds - 300:
                    cache_hit = True
                    log_entry = {
                        "url": url,
                        "event": "cache_hit",
                        "seconds": time.time() - current_epoch_seconds
                    }
                    log.write(json.dumps(log_entry) + "\n")
                    print(cache_entry["body"])
                else:
                    # Need to fetch
                    # Wait at least 0.5 seconds between retrievals
                    wait_time = max(0.5, last_retrieval_time + 0.5 - current_epoch_seconds)
                    time.sleep(wait_time)

                    try:
                        with urlopen(url, timeout=10) as response:
                            text = response.read().decode("utf-8", errors="ignore")
                            if not text.strip():
                                log_entry = {
                                    "url": url,
                                    "event": "failed",
                                    "seconds": time.time() - current_epoch_seconds
                                }
                                log.write(json.dumps(log_entry) + "\n")
                                print()
                                failed_urls += 1
                            else:
                                # Store only valid cache entry
                                cache[url] = {
                                    "retrieved_at": current_epoch_seconds,
                                    "body": text
                                }
                                log_entry = {
                                    "url": url,
                                    "event": "fetched",
                                    "seconds": time.time() - current_epoch_seconds
                                }
                                log.write(json.dumps(log_entry) + "\n")
                                print(text)
                    except (URLError, HTTPError) as e:
                        log_entry = {
                            "url": url,
                            "event": "failed",
                            "seconds": time.time() - current_epoch_seconds
                        }
                        log.write(json.dumps(log_entry) + "\n")
                        print()
                        failed_urls += 1

                # Update last retrieval time
                last_retrieval_time = current_epoch_seconds

                # Write cache to file with proper validation
                try:
                    with open(cache_file, "w", encoding="utf-8") as f:
                        # Validate cache before writing
                        valid_cache = {}
                        for url, entry in cache.items():
                            if isinstance(entry, dict):
                                if 'retrieved_at' in entry and 'body' in entry:
                                    if isinstance(entry['retrieved_at'], (int, float)) and isinstance(entry['body'], str):
                                        valid_cache[url] = entry
                        json.dump(valid_cache, f, ensure_ascii=False, indent=2)
                except (IOError, OSError) as e:
                    # Log error but continue processing
                    pass

    # Exit with status 1 if any URL failed, otherwise 0
    if failed_urls > 0:
        sys.exit(1)
    else:
        sys.exit(0)

if __name__ == "__main__":
    main()

import sys
import time
import requests
import os
import json
import urllib.parse
from urllib3.util import parse_url
from typing import Optional, Dict, Any

def validate_package_name(name: str) -> bool:
    """
    Validate package name to prevent path traversal and injection.
    Only allow alphanumeric characters, hyphens, underscores, and dots.
    """
    if not name or not isinstance(name, str):
        return False
    # Allow only safe characters: letters, digits, hyphens, underscores, dots
    allowed_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-")
    return all(c in allowed_chars for c in name)

def is_safe_url(url: str) -> bool:
    """
    Validate URL structure to prevent injection.
    Ensure the URL only contains expected components and does not contain dangerous sequences.
    """
    try:
        parsed = parse_url(url)
        if not parsed.scheme or parsed.scheme != "https":
            return False
        if not parsed.netloc or parsed.netloc != "packages.example.com":
            return False
        if not parsed.path:
            return False
        # Check for path traversal attempts
        path_parts = parsed.path.strip('/').split('/')
        if any(part.startswith('.') for part in path_parts):
            return False
        if any(part == '..' for part in path_parts):
            return False
        return True
    except Exception:
        return False

def safe_build_url(base_url: str, package_name: str) -> str:
    """
    Build a safe URL from base and package name.
    """
    # Normalize package name to ensure no dangerous characters
    safe_name = urllib.parse.quote(package_name, safe='')
    # Reconstruct URL with safe components
    return f"{base_url}/{safe_name}"

def make_request_with_retry(url: str, headers: Dict[str, str], timeout: int = 10) -> Optional[Dict[str, Any]]:
    """
    Make a secure HTTP GET request with proper error handling.
    Returns response data on success, None on failure.
    """
    try:
        response = requests.get(url, headers=headers, timeout=timeout)
        if response.status_code == 200:
            return response.json()
        return None
    except requests.exceptions.Timeout:
        return None
    except requests.exceptions.ConnectionError:
        return None
    except requests.exceptions.HTTPError as e:
        return None
    except requests.exceptions.RequestException as e:
        # Log error without exposing internal details
        return None

def main():
    token = os.getenv('PACKAGES_TOKEN')
    if not token:
        print("ERROR: PACKAGES_TOKEN environment variable is not set")
        sys.exit(1)

    # Validate token (basic check - in production, validate token format and expiry)
    if not token or len(token.strip()) == 0:
        print("ERROR: Invalid or empty PACKAGES_TOKEN")
        sys.exit(1)

    headers = {
        'Authorization': f'Bearer {token}'
    }

    base_url = "https://packages.example.com/api/v1/packages"
    request_delay = 0.2  # 200ms delay between requests

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        # Validate package name
        if not validate_package_name(line):
            print(f"{line}\t400")
            continue

        # Build safe URL
        url = safe_build_url(base_url, line)

        # Validate URL structure
        if not is_safe_url(url):
            print(f"{line}\t400")
            continue

        # Wait at least 200ms after the previous request
        time.sleep(request_delay)

        # Make request
        response_data = make_request_with_retry(url, headers)

        if response_data is not None and response_data.get('version'):
            print(f"{line}\t{response_data['version']}")
        else:
            print(f"{line}\t{response.status_code if 'status_code' in dir(response) else 400}")

