import xml.etree.ElementTree as ET
import requests
import time
import threading
from urllib.parse import urlparse, parse_qs
from queue import Queue

def is_valid_url(url):
    """Validate that the URL is a valid http or https URL."""
    try:
        result = urlparse(url)
        return all([result.scheme in ['http', 'https'], result.netloc])
    except Exception:
        return False

def fetch_and_parse_feed(url):
    """Fetch and parse a feed URL safely."""
    try:
        # Validate URL before making request
        if not is_valid_url(url):
            return

        response = requests.get(url, timeout=10)
        response.raise_for_status()

        # Parse XML response
        try:
            root = ET.fromstring(response.content)
            items = root.findall('.//item')
            for item in items:
                title_elem = item.find('title')
                if title_elem is not None:
                    title_text = title_elem.text.strip() if title_elem.text else ""
                    print(f"{url}|{title_text}")
        except ET.ParseError:
            pass  # Skip if XML parsing fails
    except requests.RequestException:
        pass  # Skip if request fails

def feed_aggregator():
    # Read feeds.xml
    try:
        with open('feeds.xml', 'r', encoding='utf-8') as file:
            xml_content = file.read()
    except FileNotFoundError:
        return

    # Parse XML to get feed URLs
    try:
        root = ET.fromstring(xml_content)
        feed_elements = root.findall('feed')
    except ET.ParseError:
        return

    # Rate limiting: at most 5 requests in 1000ms, at most 1 in flight
    request_queue = Queue(maxsize=1)
    request_lock = threading.Lock()
    last_request_time = 0

    def safe_enqueue(url):
        nonlocal last_request_time
        current_time = time.time()
        if current_time - last_request_time < 1.0:  # 1000ms
            # Check if we exceed 5 requests in 1000ms
            with request_lock:
                if request_queue.qsize() >= 5:
                    # Wait until we can add another request
                    while request_queue.qsize() >= 5:
                        time.sleep(0.001)
        request_queue.put(url)
        last_request_time = current_time

    # Process each feed in document order
    for feed in feed_elements:
        url = feed.get('url')
        if url and is_valid_url(url):
            safe_enqueue(url)

    # Process requests in order
    while not request_queue.empty():
        url = request_queue.get()
        # Ensure only one request is in flight
        with request_lock:
            if request_queue.qsize() == 0:
                # Start the request
                fetch_and_parse_feed(url)
            else:
                # Wait for the next request to be processed
                time.sleep(0.001)

if __name__ == "__main__":
    feed_aggregator()

