import sys
import xml.etree.ElementTree as ET
import hashlib
import argparse
import os
from pathlib import Path
from typing import Dict, Optional

def compute_digest(token: str, algorithm: str) -> str:
    """Compute the digest of token using the specified algorithm."""
    # Only allow safe, well-known algorithms
    valid_algorithms = {
        'md5': hashlib.md5,
        'sha1': hashlib.sha1,
        'sha256': hashlib.sha256
    }

    if algorithm not in valid_algorithms:
        raise ValueError(f"Unsupported digest algorithm: {algorithm}")

    hasher = valid_algorithms[algorithm]
    return hasher(token.encode()).hexdigest()

def validate_xml_path(config_path: str) -> bool:
    """Validate that the provided path is safe and within expected directories."""
    path = Path(config_path)
    if not path.is_absolute():
        return False
    # Restrict to known safe directories (e.g., current directory or specific trusted paths)
    if path.parent != Path.cwd() and not path.parent.is_relative_to(Path.cwd()):
        return False
    if '..' in str(path) or '~' in str(path):
        return False
    return path.is_file()

def validate_input_line(line: str) -> Optional[tuple[str, str, str]]:
    """Validate and parse an input line into token, method, and path."""
    line = line.strip()
    if not line:
        return None

    parts = line.split()
    if len(parts) != 3:
        return None

    token, method, path = parts
    # Validate token: prevent excessive length to avoid DoS
    if len(token) > 1024:
        return None

    # Validate method and path to prevent injection (though not used in logic)
    if len(method) > 1024 or len(path) > 1024:
        return None

    return token, method, path

def main():
    # Parse command-line argument with proper validation
    parser = argparse.ArgumentParser(description="Authenticate tokens based on XML configuration.")
    parser.add_argument("config_path", help="Path to XML configuration file", type=str)
    args = parser.parse_args()

    config_path = args.config_path

    # Validate the configuration file path
    if not validate_xml_path(config_path):
        sys.exit(1)

    # Parse XML configuration with strict validation
    try:
        tree = ET.parse(config_path)
        root = tree.getroot()
    except ET.ParseError as e:
        sys.exit(1)
    except FileNotFoundError:
        sys.exit(1)

    # Validate required attributes in root
    algorithm = root.get('hash')
    if not algorithm:
        sys.exit(1)

    # Validate that only allowed algorithms are used
    if algorithm not in ['md5', 'sha1', 'sha256']:
        sys.exit(1)

    # Extract user data with strict validation
    users: Dict[str, dict] = {}
    for user_elem in root.findall('user'):
        name = user_elem.get('name')
        role = user_elem.get('role')
        token_digest = user_elem.get('token_digest')

        # Validate required attributes
        if not name or not role or not token_digest:
            continue

        # Validate that role is only 'admin' or 'user' (to prevent role escalation)
        if role not in ['admin', 'user']:
            continue

        users[name] = {
            'role': role,
            'token_digest': token_digest
        }

    # Process input with rate limiting and input validation
    # Use a reasonable limit to prevent DoS
    MAX_INPUT_LINES = 10000
    line_count = 0

    for line in sys.stdin:
        line_count += 1
        if line_count > MAX_INPUT_LINES:
            sys.exit(1)  # Prevent excessive processing

        parsed = validate_input_line(line)
        if not parsed:
            continue

        token, method, path = parsed

        # Compute digest of token
        try:
            computed_digest = compute_digest(token, algorithm)
        except ValueError as e:
            sys.exit(1)

        # Find matching user with admin role
        matching_user = None
        for name, user_data in users.items():
            if user_data['token_digest'] == computed_digest and user_data['role'] == 'admin':
                matching_user = name
                break

        # Output result
        if matching_user:
            print(f"ALLOW {matching_user}")
        else:
            print("DENY")

