import sys
import xml.etree.ElementTree as ET
import json
import time
import os

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    xml_path = sys.argv[1]
    json_path = sys.argv[2]

    # Validate file paths for path traversal
    if not is_valid_path(xml_path) or not is_valid_path(json_path):
        sys.exit(1)

    try:
        token_id = sys.stdin.readline().strip()
        service_name = sys.stdin.readline().strip()
    except (IOError, OSError):
        sys.exit(1)

    if not token_id or not service_name:
        sys.exit(1)

    # Validate token ID and service name length and content
    if len(token_id) == 0 or len(service_name) == 0:
        sys.exit(1)

    # Validate token ID and service name for potential injection
    if not is_valid_token_id(token_id) or not is_valid_service_name(service_name):
        sys.exit(1)

    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except (ET.ParseError, OSError) as e:
        sys.exit(1)

    if root is None:
        sys.exit(1)

    name_attr = root.get('name')
    limit_str = root.get('limit')

    # Validate limit attribute
    if not name_attr or not limit_str:
        sys.exit(1)

    try:
        limit = int(limit_str)
    except ValueError:
        sys.exit(1)

    # Validate limit is positive and within reasonable bounds
    if limit <= 0 or limit > 1000000:
        sys.exit(1)

    # Check if token ID matches any token element
    token_found = False
    for token_elem in root.findall('.//token'):
        if token_elem.get('id') == token_id:
            token_found = True
            break

    if not token_found:
        print(f"DENY {service_name}")
        sys.exit(0)

    # Check if requested service name matches
    if service_name != name_attr:
        print(f"DENY {service_name}")
        sys.exit(0)

    # Process token bucket
    now = time.time()

    try:
        with open(json_path, 'r') as f:
            state = json.load(f)
        tokens = state.get('tokens', 0)
        last_refill = state.get('last_refill', 0)
    except (FileNotFoundError, json.JSONDecodeError):
        tokens = limit
        last_refill = now

    # Use floating-point division for accurate token calculation
    elapsed = now - last_refill
    tokens = min(limit, tokens + (elapsed * limit) / 60.0)

    if tokens >= 1:
        print(f"ALLOW {name_attr}")
        tokens -= 1
        new_state = {'tokens': tokens, 'last_refill': now}
        try:
            with open(json_path, 'w') as f:
                json.dump(new_state, f)
        except (OSError, IOError):
            sys.exit(1)
    else:
        print(f"DENY {name_attr}")

def is_valid_path(path):
    """Check if path is valid and does not contain path traversal."""
    if not path or not isinstance(path, str):
        return False
    # Prevent path traversal
    if '..' in path or '/' in path.split('\\') or '\\' in path:
        return False
    return True

def is_valid_token_id(token_id):
    """Validate token ID for length and content."""
    if not token_id or len(token_id) > 255:
        return False
    # Avoid injection-like patterns
    if ';' in token_id or '|' in token_id or '$' in token_id or '`' in token_id:
        return False
    return True

def is_valid_service_name(service_name):
    """Validate service name for length and content."""
    if not service_name or len(service_name) > 255:
        return False
    # Avoid injection-like patterns
    if ';' in service_name or '|' in service_name or '$' in service_name or '`' in service_name:
        return False
    return True

