def validate_token_lines(token_content):
    lines = token_content.splitlines()
    if len(lines) < 2:
        raise SystemExit(1)
    payload_str = lines[0].strip()
    signature_str = lines[1].strip()
    if not payload_str or not signature_str:
        raise SystemExit(1)
    return payload_str, signature_str

def parse_payload(payload_str):
    try:
        payload = json.loads(payload_str)
        if not isinstance(payload, dict):
            raise SystemExit(1)
        if "role" not in payload:
            raise SystemExit(1)
        if not isinstance(payload["role"], str):
            raise SystemExit(1)
        if "attributes" not in payload:
            payload["attributes"] = {}
        elif not isinstance(payload["attributes"], dict):
            raise SystemExit(1)
        return payload
    except json.JSONDecodeError as e:
