def evaluate_expr_safely(expr, attributes):
    # Validate and sanitize the expression
    if not isinstance(expr, str):
        return False
    # Remove any potential dangerous constructs
    # Replace only safe key-value pairs
    safe_expr = expr
    for key, value in attributes.items():
        # Validate key and value
        if not isinstance(key, str):
            return False
        # Escape key to prevent injection
        escaped_key = re.escape(key)
        # Replace only if the key is not a reserved word or dangerous
        if escaped_key.startswith('__'):
            return False
        # Convert value to string safely
        value_str = str(value)
        # Replace only if value is not a function or dangerous
        safe_expr = safe_expr.replace(f'{{"{key}"}}', value_str)
    # Validate the resulting expression
    # Only allow simple comparisons and arithmetic
    # Remove any function calls or dynamic access
    # Check for dangerous patterns
    dangerous_patterns = [
        r'\b(__import__|eval|exec|open|os|subprocess|sys|getattr|setattr|dir)\b',
        r'\b(\w+)\s*\(\s*[\w\.\[\]\s\(\)]*\s*\)',
        r'\b(\w+)\s*\[\s*\w+\s*\]'
    ]
    for pattern in dangerous_patterns:
        if re.search(pattern, safe_expr, re.IGNORECASE):
            return False
    # Evaluate only safe expressions
    try:
        # Use a restricted environment with only safe built-ins
        safe_env = {
            '__builtins__': {
                'abs': abs,
                'int': int,
                'float': float,
                'str': str,
                'len': len,
                'bool': bool,
                'type': type,
                'list': list,
                'dict': dict,
                'tuple': tuple,
                'set': set,
                'max': max,
                'min': min,
                'sum': sum,
                'all': all,
                'any': any,
                'range': range,
                'round': round,
                'pow': pow,
                'chr': chr,
                'ord': ord,
                'repr': repr,
                'hash': hash,
                'len': len,
                'isinstance': isinstance,
                'hasattr': hasattr,
                'getattr': getattr,
                'setattr': setattr,
                'dir': dir,
                'type': type,
            }
        }
        # Evaluate the expression
        result = eval(safe_expr, {"__builtins__": {}}, safe_env)
        return result
    except Exception:
        return False

def compute_signature(payload_str, key_str):
    # Use HMAC-SHA256 for secure signature
    return hmac.new(key_str.encode(), payload_str.encode(), hashlib.sha256).hexdigest()

def main():
    if len(sys.argv) != 4:
        sys.exit(1)

    flags_path = sys.argv[1]
    token_path = sys.argv[2]
    key_path = sys.argv[3]

    try:
