            if not isinstance(flag["role"], str) or not isinstance(flag["expr"], str):
                continue

            # Validate role match
            if payload["role"] != flag["role"]:
                continue

            # Evaluate expression safely
            result = evaluate_expr_safely(flag["expr"], payload.get("attributes", {}))
            print(f"{flag_name}: {result}")

    except Exception as e:
