            elif char == ')':
                paren_count -= 1
                if paren_count < 0:
                    return None
        if paren_count != 0:
            return None

        # Check for valid arithmetic operations
        # We'll use a simple token-based evaluation
        # Replace all metric names with values, then evaluate with safe arithmetic
        # We'll use a custom evaluator that only supports +, -, *, /, and parentheses
        # and only numeric values

