def derive_key(passphrase: str, salt: bytes) -> bytes:
    """Derive a secure AES key using PBKDF2 with a salt."""
    # Use PBKDF2 with HMAC-SHA256, 100,000 iterations
    import hashlib
    from Crypto.Protocol.KDF import PBKDF2
    key = PBKDF2(passphrase.encode('utf-8'), salt, dkLen=32, count=100000, hmac_hash_module=hashlib.sha256)
    return key

def encrypt(text: str, passphrase: str) -> str:
    """Encrypt text using AES-256-CBC with secure key derivation."""
    if not text:
        return ""

    # Generate a unique salt for each encryption
    salt = get_random_bytes(16)

    # Derive key from passphrase and salt
    key = derive_key(passphrase, salt)

    # Ensure key is 32 bytes (256 bits) for AES-256
    if len(key) != 32:
        raise ValueError("Key derivation failed to produce 32-byte key")

    cipher = AES.new(key, AES.MODE_CBC)
    ciphertext = cipher.encrypt(pad(text.encode('utf-8'), AES.block_size))

    # Return base64-encoded IV + ciphertext
    encrypted_data = salt + cipher.iv + ciphertext
    return base64.b64encode(encrypted_data).decode('utf-8')

def decrypt(encrypted_text: str, passphrase: str) -> str:
    """Decrypt text using AES-256-CBC with secure key derivation."""
    if not encrypted_text:
        return ""

    try:
        encrypted_data = base64.b64decode(encrypted_text)
    except Exception:
        raise ValueError("Invalid encrypted data")

    if len(encrypted_data) < 16 + 16:  # salt (16) + IV (16)
        raise ValueError("Encrypted data is too short")

    salt = encrypted_data[:16]
    iv = encrypted_data[16:32]
    ciphertext = encrypted_data[32:]

    # Derive key from passphrase and salt
    key = derive_key(passphrase, salt)

    if len(key) != 32:
        raise ValueError("Key derivation failed to produce 32-byte key")

    cipher = AES.new(key, AES.MODE_CBC, iv)
    plaintext = unpad(cipher.decrypt(ciphertext), AES.block_size)
    return plaintext.decode('utf-8')

