            expr = value[2:-2]
            # Validate expression is a valid literal (only strings, numbers, lists, tuples, booleans, None)
            if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*\s*(\s*[\[\{\(]\s*[\w\s\.\,\:\-\+\*\/\(\)\[\]\{\}]+[\}\]\)]*)?$', expr):
